// fix-loop-input-007-clarification-eof-stops: A clarifying question with stdin at end of input prints the question and suggestions, requires a person and stops without guessing
func TestFixLoopInput007ClarificationEofStops(t *testing.T) {
	s := scenarios.New(t, "fix-loop-input-007-clarification-eof-stops")
	s.Given(`the "fix-loop-unanswered-eof" project tree`)
	s.When(`the Quality Engineer runs "scen check --fix"`)
	s.Then(`the command exits with code 1`)
	s.And(`stdout matches What does the step "the service answers within 200 milliseconds" mean`)
	s.And(`stdout matches It means its reply arrives no later than that many milliseconds after the message was sent.`)
	s.And(`stdout matches It means the time from sending the message to its reply arriving is at most that many milliseconds.`)
	s.And(`stdout matches a person must answer`)
	s.And(`stderr matches a person must answer`)
	s.And(`stdout does not match User answered clarification question`)
	s.And(`stdout does not match SCEN CHECK COMPLETE`)
	s.And(`the engine dispatched 1 AI turn`)
	s.And(`no file outside "tmp" changed`)
	s.Done()
}

// fix-loop-input-008-menu-eof-stops: End of input at the fix menu stops because a person must choose, without a tests-still-failing error or completion banner
func TestFixLoopInput008MenuEofStops(t *testing.T) {
	s := scenarios.New(t, "fix-loop-input-008-menu-eof-stops")
	s.Given(`the "fix-loop-menu-eof" project tree`)
	s.And(`the project's test dependencies are installed`)
	s.When(`the System Architect runs "build code --fix"`)
	s.Then(`the command exits with code 1`)
	s.And(`stdout matches end of input at fix menu; a person must choose whether to apply the fix`)
	s.And(`stderr matches end of input at fix menu; a person must choose whether to apply the fix`)
	s.And(`stdout does not match tests still failing`)
	s.And(`stderr does not match tests still failing`)
	s.And(`stdout does not match BUILD CODE COMPLETE`)
	s.And(`the engine dispatched 1 AI turn`)
	s.And(`no file outside "tmp" changed`)
	s.Done()
}
